   106	    public ItemProcessor<Xfr60, Xfr60> shipmentItemProcessor() {
   107	        log.debug("배송 상태 업데이트 ItemProcessor 구성");
   108	
   109	
   110	        return orderShipment -> {
   111	            String trackingNumber = orderShipment.getTrackingNumber();
   112	            Long shipmentId = orderShipment.getId();
   113	
   114	            if (trackingNumber == null || trackingNumber.isBlank()) {
   115	                log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
   116	                throw new Xzn53Exception(Xzn53ErrorCode.TRACKING_NUMBER_INVALID);
   117	            }
   118	
   119	            log.info("배송 상태 조회 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
   120	                    shipmentId, trackingNumber, orderShipment.getStatus());
   121	
   122	            try {
   123	
   124	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
   125	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}", shipmentId, currentStatus);
   126	
   127	
   128	                Xzn53Status newStatus = mapToShipmentStatus(currentStatus);
   129	                log.debug("배송 상태 매핑 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
   130	
   131	
   132	                if (orderShipment.getStatus() == newStatus) {
   133	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
   134	                            shipmentId, newStatus);
   135	                    return orderShipment;
   136	                }
   137	
   138	
   139	                if (newStatus == Xzn53Status.DELIVERED) {
   140	                    log.info("배송 완료 처리: shipmentId={}, orderId={}",
   141	                            shipmentId, orderShipment.getOrder().getId());
   142	
   143	                    orderShipment.updateStatus(Xzn53Status.DELIVERED);
   144	
   145	                    orderService.completeOrder(orderShipment.getOrder().getId());
   146	
   147	                    notificationService.notifyShipmentCompleted(orderShipment.getOrder());
   148	                }
   149	                else if (newStatus == Xzn53Status.OUT_FOR_DELIVERY) {
   150	                    log.info("배송 출발 처리: shipmentId={}", shipmentId);
   151	                    orderShipment.updateStatus(Xzn53Status.OUT_FOR_DELIVERY);
   152	
   153	                }
   154	                else {
   155	                    log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
   156	                    orderShipment.updateStatus(Xzn53Status.IN_TRANSIT);
   157	                }
   158	
   159	                log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}", shipmentId, orderShipment.getStatus());
   160	                return orderShipment;
   161	
   162	            } catch (Exception e) {
   163	                log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
   164	                        shipmentId, trackingNumber, e.getMessage(), e);
   165	
   166	
   167	                if (!(e instanceof Xzn53Exception)) {
   168	                    throw new Xzn53Exception(
   169	                            Xzn53ErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
   170	                            "배송 상태 조회 중 오류 발생: " + e.getMessage(),
   171	                            e
   172	                    );
   173	                }
   174	                throw e;
   175	            }
   176	        };
   177	    }
